# Generated by build.py from recipe.yml for recipe http-upload-several-files-at-once. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site/reports site/inbox drop
printf '%s\n' 'alpha' > a.txt
printf '%s\n' 'bravo' > b.txt
printf '%s\n' 'charlie' > c.txt
printf '%s\n' 'from last week' > site/reports/old.txt
printf '%s\n' 'keep' > site/inbox/keep.txt
printf '%s\n' 'uploads land here' > drop/readme.txt
surl --directory site --allow-uploads --allow-anonymous --list-directories http://127.0.0.1:8080/ ws://127.0.0.1:8081/ &
sleep 1
curl -s -T "{a,b,c}.txt" -w "%{http_code} %{url.path}\n" http://127.0.0.1:8080/reports/ --next ws://127.0.0.1:8081/reports/
kill $(jobs -p)
